  const dateLabel=date=>{if(!date)return 'Inte separat verifierat';const p=date.split('-');return p.length===3 ? new Date(date+'T12:00:00Z').toLocaleDateString('sv-SE',{year:'numeric',month:'long',day:'numeric',timeZone:'UTC'}) : date;};
